insert into Mail_UserLog (UserId,TypeOfUser,SystemBased,MessageId,FolderName) select distinct UserId, ,1, ,
from AC_User WITH (NOLOCK)
union select distinct ExternalUserId, ,0, ,
from mail_externalUsers WITH (NOLOCK)
